from datetime import datetime, timezone
from sqlalchemy import (
    BigInteger,
    Boolean,
    Column,
    DateTime,
    Float,
    Index,
    Integer,
    String,
    Text,
    func,
)
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.types import JSON

from app.db.base import Base

# Use JSONB on PostgreSQL, standard JSON on SQLite/other engines
JSONType = JSON().with_variant(JSONB, "postgresql")
IDType = BigInteger().with_variant(Integer, "sqlite")


class SensorReadingModel(Base):
    """Time-series sensor telemetry readings generated by the induction motor simulator."""

    __tablename__ = "sensor_readings"

    id = Column(IDType, primary_key=True, autoincrement=True)
    device_id = Column(String(64), nullable=False, index=True)
    timestamp = Column(DateTime(timezone=True), nullable=False, index=True)
    temperature = Column(Float, nullable=False)
    vibration = Column(Float, nullable=False)
    rpm = Column(Float, nullable=False)
    mode = Column(String(32), nullable=False, default="normal")
    is_running = Column(Boolean, nullable=False, default=True)
    sequence = Column(BigInteger, nullable=False, index=True)
    created_at = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)

    __table_args__ = (
        Index("ix_sensor_readings_device_time", "device_id", "timestamp"),
        Index("ix_sensor_readings_seq_device", "device_id", "sequence"),
    )

    def to_dict(self) -> dict:
        """Convert model attributes to a standard dictionary representation."""
        return {
            "id": self.id,
            "device_id": self.device_id,
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "temperature": self.temperature,
            "vibration": self.vibration,
            "rpm": self.rpm,
            "mode": self.mode,
            "is_running": self.is_running,
            "sequence": self.sequence,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class AIPredictionModel(Base):
    """Historical records of Isolation Forest anomaly detection evaluations."""

    __tablename__ = "ai_predictions"

    id = Column(IDType, primary_key=True, autoincrement=True)
    device_id = Column(String(64), nullable=False, index=True)
    timestamp = Column(DateTime(timezone=True), nullable=False, index=True)
    is_anomaly = Column(Boolean, nullable=False, index=True)
    prediction = Column(Integer, nullable=False)  # 1 for inlier, -1 for anomaly
    anomaly_score = Column(Float, nullable=False)
    model_name = Column(String(64), nullable=False)
    model_version = Column(String(32), nullable=False)
    source = Column(String(64), nullable=False, index=True)  # live_simulator_stream / user_telemetry_submission
    features_evaluated = Column(JSONType, nullable=False)
    diagnostic_context = Column(JSONType, nullable=True)
    created_at = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)

    __table_args__ = (
        Index("ix_ai_predictions_device_anomaly", "device_id", "is_anomaly", "timestamp"),
    )

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "device_id": self.device_id,
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "is_anomaly": self.is_anomaly,
            "prediction": self.prediction,
            "anomaly_score": self.anomaly_score,
            "model_name": self.model_name,
            "model_version": self.model_version,
            "source": self.source,
            "features_evaluated": self.features_evaluated,
            "diagnostic_context": self.diagnostic_context,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class AlertRecordModel(Base):
    """Operational machine alerts, severity levels, and operator acknowledgment status."""

    __tablename__ = "alert_records"

    id = Column(String(64), primary_key=True)  # Alert UUID
    episode_id = Column(String(64), nullable=False, index=True)
    device_id = Column(String(64), nullable=False, index=True)
    alert_type = Column(String(64), nullable=False)
    severity = Column(String(32), nullable=False, index=True)  # warning / critical
    title = Column(String(255), nullable=False)
    message = Column(Text, nullable=False)
    status = Column(String(32), nullable=False, index=True, default="active")  # active / acknowledged / dismissed
    timestamp = Column(DateTime(timezone=True), nullable=False, index=True)
    acknowledged_at = Column(DateTime(timezone=True), nullable=True)
    acknowledged_by = Column(String(128), nullable=True)
    dismissed_at = Column(DateTime(timezone=True), nullable=True)
    anomaly_score = Column(Float, nullable=True)
    sensor_snapshot = Column(JSONType, nullable=False)
    created_at = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)

    __table_args__ = (
        Index("ix_alert_records_status_time", "status", "timestamp"),
        Index("ix_alert_records_device_status", "device_id", "status"),
    )

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "episode_id": self.episode_id,
            "device_id": self.device_id,
            "alert_type": self.alert_type,
            "severity": self.severity,
            "title": self.title,
            "message": self.message,
            "status": self.status,
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "acknowledged_at": self.acknowledged_at.isoformat() if self.acknowledged_at else None,
            "acknowledged_by": self.acknowledged_by,
            "dismissed_at": self.dismissed_at.isoformat() if self.dismissed_at else None,
            "anomaly_score": self.anomaly_score,
            "sensor_snapshot": self.sensor_snapshot,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class WhatIfExperimentModel(Base):
    """Saved hypothetical operational scenarios and Isolation Forest counterfactual results."""

    __tablename__ = "whatif_experiments"

    id = Column(String(64), primary_key=True)  # e.g. exp-1729831923
    name = Column(String(255), nullable=False)
    timestamp = Column(DateTime(timezone=True), nullable=False, index=True)
    temperature = Column(Float, nullable=False)
    vibration = Column(Float, nullable=False)
    rpm = Column(Float, nullable=False)
    is_anomaly = Column(Boolean, nullable=False, index=True)
    prediction = Column(Integer, nullable=False)
    anomaly_score = Column(Float, nullable=False)
    baseline_snapshot = Column(JSONType, nullable=True)
    created_at = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "name": self.name,
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "temperature": self.temperature,
            "vibration": self.vibration,
            "rpm": self.rpm,
            "is_anomaly": self.is_anomaly,
            "prediction": self.prediction,
            "anomaly_score": self.anomaly_score,
            "baseline_snapshot": self.baseline_snapshot,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }


class UserModel(Base):
    """User account credentials and profile metadata for simulator authentication."""

    __tablename__ = "users"

    id = Column(String(64), primary_key=True)  # UUID string e.g. user_...
    email = Column(String(255), unique=True, nullable=False, index=True)
    full_name = Column(String(255), nullable=False)
    hashed_password = Column(String(255), nullable=False)
    is_active = Column(Boolean, nullable=False, default=True)
    created_at = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)
    last_login_at = Column(DateTime(timezone=True), nullable=True)

    def to_safe_dict(self) -> dict:
        """Convert model attributes to dictionary, strictly excluding password hash."""
        return {
            "id": self.id,
            "email": self.email,
            "name": self.full_name,
            "is_active": self.is_active,
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "last_login_at": self.last_login_at.isoformat() if self.last_login_at else None,
        }

    def to_dict(self) -> dict:
        """Standard representation returning safe attributes."""
        return self.to_safe_dict()
